args.command:
perl -e '
use strict;
use warnings;
use File::Find;

my $repo = "/bench/repo";
my $internal = "$repo/internal";

my @decls;
find(sub {
  return unless /\.go$/ && !/_test\.go$/;
  my $path = $File::Find::name;
  my $rel = $path;
  $rel =~ s#^\Q$repo/\E##;
  open my $fh, "<", $path or die $!;
  my $i = 0;
  while (my $line = <$fh>) {
    $i++;
    if ($line =~ /^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/) {
      push @decls, { name => $2, recv => ($1 // "-"), path => $rel, line => $i };
    }
  }
}, $internal);

print "Total declarations: ", scalar(@decls), "\n";
my %byname;
for my $d (@decls) { $byname{$d->{name}}++; }
print "Unique names: ", scalar(keys %byname), "\n";
print "Name collisions:\n";
for my $n (sort { $byname{$b} <=> $byname{$a} } keys %byname) {
  last if $byname{$n} < 2;
  print "  $n: $byname{$n}\n";
}
print "\nALL\n";
for my $d (@decls) {
  print "$d->{name}\t$d->{recv}\t$d->{path}:$d->{line}\n";
}
'

find /bench/repo/internal -name "*.go" ! -name "*_test.go" -print0 | xargs -0 awk '
/^func[[:space:]]+/ {
  line = $0
  recv = "-"
  name = ""
  if (match(line, /^func[[:space:]]+\(([^)]+)\)[[:space:]]+([A-Za-z_][A-Za-z0-9_]*)[[:space:]]*\(/, a)) {
    recv = a[1]
    name = a[2]
  } else if (match(line, /^func[[:space:]]+([A-Za-z_][A-Za-z0-9_]*)[[:space:]]*\(/, a)) {
    name = a[1]
  }
  if (name != "") {
    printf "%s\t%s\t%s:%d\n", name, recv, FILENAME, FNR
  }
}
'

find /bench/repo/internal -name "*.go" ! -name "*_test.go" | while read f; do
  perl -ne '
    if (/^func\s+(?:\(([^)]+)\)\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(/) {
      my $recv = defined $1 ? $1 : "-";
      print "$2\t$recv\t'"$f"':$.\n";
    }
  ' "$f"
done
